// TestReadDispatchPending_MtimeTieBreaksOnMissionID pins review finding
// L5 (full-branch review, m-2026-09-08-004 round 3): two pending-dispatch
// entries written with identical mtimes (a real possibility on
// filesystems with coarse mtime resolution, or two writers landing in
// the same tick) must still sort deterministically, oldest-by-ID, not by
// sort.Slice's documented unspecified order for equal comparator keys.
//
// Confirmed failing against the pre-fix code: pinning both files to the
// same mtime made the returned order flip depending on directory read
// order rather than staying fixed at (older-ID-first).
func TestReadDispatchPending_MtimeTieBreaksOnMissionID(t *testing.T) {
	root := t.TempDir()
	sess := "sess-mtime-tie"
	older := "m-2026-09-08-100"
	newer := "m-2026-09-08-200"

	// Write in an order that would expose a wrong tiebreak: the
	// lexically-later ID first, then force both files to the exact same
	// mtime so CreatedAt carries no information at all.
	require.NoError(t, WriteDispatchPending(root, sess, newer, "bwk"))
	require.NoError(t, WriteDispatchPending(root, sess, older, "bwk"))
	tie := time.Now()
	require.NoError(t, os.Chtimes(DispatchPendingPath(root, sess, older), tie, tie))
	require.NoError(t, os.Chtimes(DispatchPendingPath(root, sess, newer), tie, tie))

	entries, warnings, err := ReadDispatchPending(root, sess)
	require.NoError(t, err)
	assert.Empty(t, warnings)
	require.Len(t, entries, 2)
	assert.Equal(t, older, entries[0].MissionID,
		"an exact mtime tie must break on mission ID, not on directory read order")
	assert.Equal(t, newer, entries[1].MissionID)
}

// TestReadDispatchPending_RefusesSymlink pins the second half of L5: a
// symlinked pending-dispatch entry must be refused, matching
// LoadDelegation's own rejectSymlink discipline, rather than silently
// followed via a plain os.ReadFile.
func TestReadDispatchPending_RefusesSymlink(t *testing.T) {
	root := t.TempDir()
	sess := "sess-dispatch-symlink"
	missionID := "m-2026-09-08-300"

	outside := filepath.Join(t.TempDir(), "worker.txt")
	require.NoError(t, os.WriteFile(outside, []byte("bwk\n"), 0o600))

	path := DispatchPendingPath(root, sess, missionID)
	require.NoError(t, os.MkdirAll(filepath.Dir(path), 0o700))
	require.NoError(t, os.Symlink(outside, path))

	entries, warnings, err := ReadDispatchPending(root, sess)
	require.NoError(t, err)
	assert.Empty(t, entries, "a symlinked entry must not be returned as a live pending dispatch")
	require.Len(t, warnings, 1)
	assert.Contains(t, warnings[0], "refusing to follow symlink")
